import{_ as r,C as i,o as t,c as l,a2 as a,b as c,w as o,a as s,E as u,a3 as n}from"./chunks/framework.DZUUNQ77.js";const M=JSON.parse('{"title":"OSUtils · 系统 ROM 识别","description":"","frontmatter":{},"headers":[],"relativePath":"reference/helper/utils/os-utils.md","filePath":"reference/helper/utils/os-utils.md","lastUpdated":1784063681000}'),p={name:"reference/helper/utils/os-utils.md"};function m(E,e,h,b,A,_){const d=i("Mermaid");return t(),l("div",null,[e[1]||(e[1]=a('<h1 id="osutils-·-系统-rom-识别" tabindex="-1">OSUtils · 系统 ROM 识别 <a class="header-anchor" href="#osutils-·-系统-rom-识别" aria-label="Permalink to &quot;OSUtils · 系统 ROM 识别&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">源码路径</p><p><a href="https://github.com/android-security-engineer/VirtualXposed-skills/blob/vxp/VirtualApp/lib/src/main/java/com/lody/virtual/helper/utils/OSUtils.java" target="_blank" rel="noreferrer"><code>src/main/java/com/lody/virtual/helper/utils/OSUtils.java</code></a></p></div><p><code>OSUtils</code> 识别当前设备跑的是哪家厂商 ROM（华为 EMUI / 小米 MIUI / 魅族 Flyme），用于针对厂商差异做兼容分支。它是单例，构造时一次性读取 <code>build.prop</code>。</p><h2 id="识别原理" tabindex="-1">识别原理 <a class="header-anchor" href="#识别原理" aria-label="Permalink to &quot;识别原理&quot;">​</a></h2><p>构造函数读取 <code>/system/build.prop</code>（<code>Environment.getRootDirectory()/build.prop</code>）到 <code>Properties</code>，按 key 探测：</p><table tabindex="0"><thead><tr><th>ROM</th><th>探测 key</th></tr></thead><tbody><tr><td>EMUI（华为）</td><td><code>ro.build.version.emui</code> 非空</td></tr><tr><td>MIUI（小米）</td><td><code>ro.miui.ui.version.code</code> / <code>.name</code> / <code>ro.miui.internal.storage</code> 任一非空</td></tr><tr><td>Flyme（魅族）</td><td>反射 <code>Build.hasSmartBar()</code> 方法存在</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">为什么用 build.prop</p><p>厂商定制信息不在标准 <code>Build</code> 字段里，只能从 <code>build.prop</code> 的 property 读。读取失败（文件不存在/无权限）时三个标志都保持 <code>false</code>，不影响流程。</p></div><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>作用</th></tr></thead><tbody><tr><td><code>getInstance()</code></td><td>取单例</td></tr><tr><td><code>isEmui()</code></td><td>是否华为 EMUI</td></tr><tr><td><code>isMiui()</code></td><td>是否小米 MIUI</td></tr><tr><td><code>isFlyme()</code></td><td>是否魅族 Flyme</td></tr><tr><td><code>getMiuiVersion()</code></td><td>MIUI 版本号字符串</td></tr></tbody></table><h2 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p>厂商 ROM 在角标、通知、权限、Stub Activity 栈管理等处有差异。例如角标协议各家不同（见 <a href="./../../client/badger">badger</a>），通知栏渲染 MIUI 有特殊处理。<code>OSUtils</code> 让这些分支可读。</p><h2 id="rom-识别决策" tabindex="-1">ROM 识别决策 <a class="header-anchor" href="#rom-识别决策" aria-label="Permalink to &quot;ROM 识别决策&quot;">​</a></h2>',12)),(t(),c(n,null,{default:o(()=>[u(d,{id:"mermaid-126",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROP%5B%22%E8%AF%BB%20%2Fsystem%2Fbuild.prop%22%5D%20--%3E%20EMUI%7B%22ro.build.version.emui%3Cbr%2F%3E%E9%9D%9E%E7%A9%BA%3F%22%7D%0A%20%20PROP%20--%3E%20MIUI%7B%22ro.miui.ui.version.code%3Cbr%2F%3E%E9%9D%9E%E7%A9%BA%3F%22%7D%0A%20%20PROP%20--%3E%20FLYME%7B%22Build.hasSmartBar()%3Cbr%2F%3E%E5%8F%8D%E5%B0%84%E5%AD%98%E5%9C%A8%3F%22%7D%0A%20%20EMUI%20--%3E%7C%22%E6%98%AF%22%7C%20E%5B%22isEmui%3Dtrue%22%5D%0A%20%20MIUI%20--%3E%7C%22%E6%98%AF%22%7C%20M%5B%22isMiui%3Dtrue%20%2B%20%E7%89%88%E6%9C%AC%22%5D%0A%20%20FLYME%20--%3E%7C%22%E6%98%AF%22%7C%20F%5B%22isFlyme%3Dtrue%22%5D%0A%20%20E%20--%3E%20BRANCH%5B%22%E8%A7%92%E6%A0%87%2F%E9%80%9A%E7%9F%A5%E7%AD%89%3Cbr%2F%3E%E5%8E%82%E5%95%86%E5%85%BC%E5%AE%B9%E5%88%86%E6%94%AF%22%5D%0A%20%20M%20--%3E%20BRANCH%0A%20%20F%20--%3E%20BRANCH%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>读取失败时三个标志保持 <code>false</code>，不影响流程。与 <a href="./../compat/build-compat"><code>BuildCompat</code></a> 互补：<code>BuildCompat</code> 管 API 等级，<code>OSUtils</code> 管厂商。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>角标适配见 <a href="./../../client/badger"><code>client/badger</code></a>。</li><li>与 <a href="./../compat/build-compat"><code>BuildCompat</code></a> 互补：前者管厂商、后者管 API 等级。</li></ul>',3))])}const f=r(p,[["render",m]]);export{M as __pageData,f as default};
